/// `MummifiedHand.after_card_played` — when a Power card is played, pick a
/// random card in hand and make it free this turn. v0.107.1 reworks the
/// candidate selection to be **cost-favorable to the player** via a
/// four-pool fallback (`MummifiedHand.cs:18-42`,
/// `sts2-rs-v0107-content-port-wb8lk.9` §7):
///
/// [decompiled C# omitted — see the cited path]
///
/// `NextItem(empty)` returns `default` **without** consuming an RNG roll
/// (`Rng.cs:256-266`: `count == 0` short-circuits before `NextInt`), so
/// the single `CombatCardSelection` roll lands on the FIRST non-empty
/// pool — exactly what the sequential-fallback walk below reproduces.
///
/// - `favorable` (`list`): base energy cost (`CostModifiers.None`) > 0 OR
///   base star cost > 0 — the cards worth freeing (intrinsic positive cost).
/// - `costs_now` (`CostsEnergyOrStars(globalMods: true)`): still costs
///   energy or stars after global modifiers (i.e. not already freed).
///
/// Fidelity caveat: X-cost cards are excluded from `favorable` (their
/// `GetWithModifiers(None)` is a sentinel, not a positive base) but remain
/// eligible via the full-hand pool (4), matching C#'s `cards` fallback.
/// Bead `sts2-rs-l36v` (initial) / `…wb8lk.9` (v0.107.1 multi-pool).
pub(crate) fn on_after_card_played_mummified_hand(
    state: &mut CombatState,
    ctx: &CardEventCtx,
) -> EffectResult {
    if !player_owns_relic(state, crate::RelicKind::MummifiedHand) {
        return EffectResult::NotImplemented;
    }
    let Some(played_uid) = ctx.card_uid else {
        return EffectResult::NotImplemented;
    };
    let is_power = crate::card_by_uid(&state.cards, played_uid)
        .is_some_and(|c| c.card_type == crate::cards::CardType::Power);
    if !is_power {
        return EffectResult::NotImplemented;
    }
    let hand: Vec<crate::CardUid> = state.player.hand.iter().copied().collect();
    // `favorable` = base energy cost > 0 OR base star cost > 0
    // (`CostModifiers.None` — intrinsic cost, ignoring local discounts).
    let is_favorable = |uid: &crate::CardUid| {
        crate::card_by_uid(&state.cards, *uid).is_some_and(|c| {
            (c.cost > 0 && !c.is_x_cost()) || crate::card_base_star_cost(c.card_id) > 0
        })
    };
    // `costs_now` = `CostsEnergyOrStars(includeGlobalModifiers: true)`: the
    // card still costs energy or stars after global modifiers (FreeThisTurn /
    // FreeUntilPlayed zero the energy side; `effective_star_cost` folds the
    // free markers on the star side).
    let costs_now = |uid: &crate::CardUid| {
        crate::card_by_uid(&state.cards, *uid).is_some_and(|c| {
            let energy_now = c.cost > 0
                && !c.is_x_cost()
                && c.combat_var(crate::cards::VarKey::FreeThisTurn) == 0
                && c.combat_var(crate::cards::VarKey::FreeUntilPlayed) == 0;
            energy_now || crate::effective_star_cost(c) > 0
        })
    };
    // Four pools, in C# fallback order. The first non-empty one is rolled.
    let pool1: Vec<crate::CardUid> = hand
        .iter()
        .copied()
        .filter(|u| is_favorable(u) && costs_now(u))
        .collect();
    let pool2: Vec<crate::CardUid> = hand.iter().copied().filter(|u| costs_now(u)).collect();
    let pool3: Vec<crate::CardUid> = hand.iter().copied().filter(|u| is_favorable(u)).collect();
    let Some(pool) = [pool1, pool2, pool3, hand]
        .into_iter()
        .find(|p| !p.is_empty())
    else {
        return EffectResult::NotImplemented;
    };
    // C# `MummifiedHand.AfterCardPlayed` rolls on `RunState.Rng.CombatCardSelection`
    // via `NextItem` (== `NextInt(0, count)`, exclusive high). Use the dedicated
    // `combat_card_selection` named stream, NOT the legacy generic `state.rng`
    // (un-migrated callsite per bead `sts2-rs-943w7`) — the generic stream is a
    // different RNG, so a roll off it picks a different card than the C# oracle.
    let chosen_uid = pool[state
        .run_rng
        .combat_card_selection
        .next_int_exclusive(0, pool.len() as i32) as usize];
    // C# `CardModel.SetToFreeThisTurn()` is a THIS-TURN modifier (cleared at
    // turn end via the `FreeThisTurn` reset), NOT a permanent cost mutation.
    // Stamping `VarKey::FreeThisTurn` makes `effective_card_cost`/
    // `effective_star_cost` charge 0 for the rest of the turn; writing
    // `card.cost = 0` directly would leave a zeroed-but-unplayed card stuck at
    // 0 forever once it cycles discard → draw into a later turn (Regent seed
    // 1005: a Mummified-Hand-freed Strike stayed free two turns later).
    crate::card_effects::set_card_var(state, chosen_uid, crate::cards::VarKey::FreeThisTurn, 1);
    EffectResult::Resolved
}

pub(crate) fn install() {
    register_after_card_played(
        RelicId::MummifiedHand,
        on_after_card_played_mummified_hand as AfterCardPlayedFn,
    );
}
